/* ==========================================================================
   Network map: Sites, MikroTik devices, Subscribers, Links
   ========================================================================== */
(function (window, document) {
  'use strict';

  var cfgNode = document.getElementById('map-config');
  var holder = document.getElementById('net-map');
  if (!cfgNode || !holder || !window.L || !window.SNGeo) { return; }

  var L = window.L;
  var SN = window.SN;
  var cfg = JSON.parse(cfgNode.textContent);
  var esc = SN.esc;

  var map = L.map(holder, { zoomControl: true, worldCopyJump: true });
  map.setView([cfg.view[0], cfg.view[1]], cfg.view[2]);
  SNGeo.attachLayers(map);

  var groups = {
    links: L.layerGroup().addTo(map),
    subscribers: L.layerGroup().addTo(map),
    sites: L.layerGroup().addTo(map),
    nodes: L.layerGroup().addTo(map),
    routers: L.layerGroup().addTo(map)
  };
  var markers = { sites: {}, routers: {}, nodes: {}, subscribers: {}, links: {} };
  var data = { sites: [], routers: [], nodes: [], subscribers: [], links: [] };
  var mode = '';            // '' | add | router | move | link
  // طرف Link: Site, MikroTik device, or Router on the map
  var KIND_OF = { site: 'sites', router: 'routers', node: 'nodes' };
  var linkFrom = null;
  var firstLoad = true;

  var ROUTER_STATUS = { online: ['Connected', 'badge-success', 'is-online'], offline: ['Offline', 'badge-danger', 'is-offline'], unknown: ['Unknown', 'badge-outline', 'is-unknown'] };
  var SUB_STATE = {
    active: ['Active', 'badge-success', 'is-active'], expiring: ['Expiring soon', 'badge-warning', 'is-expiring'],
    expired: ['Expired', 'badge-danger', 'is-expired'], suspended: ['Suspended', 'badge-danger', 'is-expired'], 'new': ['Awaiting activation', 'badge-info', 'is-new']
  };
  var LINK_STYLE = {
    fiber: { color: '#f97316', weight: 4, opacity: 0.9 },
    wireless: { color: '#2563eb', weight: 3, opacity: 0.9, dashArray: '8 7' },
    cable: { color: '#64748b', weight: 3, opacity: 0.9 },
    other: { color: '#a855f7', weight: 2, opacity: 0.9, dashArray: '2 7' }
  };

  function url(path) { return cfg.base + path; }

  // ------------------------------------------------------------------------
  // النوافذ المنبثقة
  // ------------------------------------------------------------------------
  function sitePopup(s) {
    var t = cfg.siteTypes[s.type] || { label: s.type };
    var rows = '<div class="pop-sub">' + esc(t.label) + (s.area ? ' · ' + esc(s.area) : '') + (s.height ? ' · ' + s.height + ' m' : '') + '</div>' +
      '<div class="pop-stats"><span>' + SN.icon('router') + SN.fmtNum(s.routers) + '</span>' +
      (cfg.canSubs ? '<span>' + SN.icon('users') + SN.fmtNum(s.subscribers) + '</span>' : '') +
      '<span>' + SN.icon('hard-drive') + SN.fmtNum(s.units) + '</span></div>' +
      (s.address ? '<div class="pop-sub">' + esc(s.address) + '</div>' : '');
    var actions = '<a class="btn btn-xs" href="' + url('/sites/' + s.id) + '">' + SN.icon('info') + 'Details</a>';
    if (cfg.canManage) {
      actions += '<button type="button" class="btn btn-xs" data-pop="edit-site" data-id="' + s.id + '">' + SN.icon('pencil') + 'Edit</button>' +
        '<button type="button" class="btn btn-xs" data-pop="link-from" data-of="site" data-id="' + s.id + '">' + SN.icon('waypoints') + 'Link</button>';
    }
    return '<div class="pop"><div class="pop-title">' + esc(s.name) + '</div>' + rows + '<div class="pop-actions">' + actions + '</div></div>';
  }

  function routerPopup(r) {
    var st = ROUTER_STATUS[r.status] || ROUTER_STATUS.unknown;
    return '<div class="pop"><div class="pop-title">' + esc(r.name) + '</div>' +
      '<div class="pop-sub"><span class="badge ' + st[1] + '">' + st[0] + '</span>' + (r.site ? ' · ' + esc(r.site) : '') + '</div>' +
      '<div class="pop-stats"><span>' + SN.icon('users') + SN.fmtNum(r.clients) + ' Connected</span>' + (r.cpu !== null ? '<span>' + SN.icon('cpu') + r.cpu + '%</span>' : '') + '</div>' +
      '<div class="pop-actions"><a class="btn btn-xs" href="' + url('/routers/' + r.id) + '">' + SN.icon('router') + 'Open MikroTik device</a>' +
      (cfg.canManage ? '<button type="button" class="btn btn-xs" data-pop="edit-router" data-id="' + r.id + '">' + SN.icon('pencil') + 'Name and location</button>' +
        '<button type="button" class="btn btn-xs" data-pop="link-from" data-of="router" data-id="' + r.id + '">' + SN.icon('waypoints') + 'Link</button>' : '') +
      (cfg.canManage && r.own ? '<button type="button" class="btn btn-xs text-danger" data-pop="unplace-router" data-id="' + r.id + '">' + SN.icon('trash-2') + 'Remove from map</button>' : '') +
      '</div></div>';
  }

  function nodePopup(n) {
    return '<div class="pop"><div class="pop-title">' + esc(n.name) + '</div>' +
      (cfg.canManage ? '<div class="pop-actions"><button type="button" class="btn btn-xs" data-pop="edit-node" data-id="' + n.id + '">' + SN.icon('pencil') + 'Edit</button>' +
        '<button type="button" class="btn btn-xs" data-pop="link-from" data-of="node" data-id="' + n.id + '">' + SN.icon('waypoints') + 'Link</button></div>' : '') +
      '</div>';
  }

  function subPopup(s) {
    var st = SUB_STATE[s.state] || SUB_STATE.active;
    return '<div class="pop"><div class="pop-title">' + esc(s.name) + '</div>' +
      '<div class="pop-sub"><span class="badge ' + st[1] + '">' + st[0] + '</span>' + (s.online ? ' <span class="badge badge-success badge-dot">Online now</span>' : '') + '</div>' +
      '<div class="pop-sub">' + esc(s.plan) + (s.site ? ' · ' + esc(s.site) : '') + '</div>' +
      '<div class="pop-actions"><a class="btn btn-xs" href="' + url('/subscribers/' + s.id) + '">' + SN.icon('user') + 'Open subscriber</a></div></div>';
  }

  // ------------------------------------------------------------------------
  // الرسم (Refresh in مكانه دون Close النوافذ Open)
  // ------------------------------------------------------------------------
  function sync(kind, list, build, update) {
    var seen = {};
    list.forEach(function (item) {
      seen[item.id] = true;
      var m = markers[kind][item.id];
      if (m) { update(m, item); } else { markers[kind][item.id] = build(item).addTo(groups[kind]); }
    });
    Object.keys(markers[kind]).forEach(function (id) {
      if (!seen[id]) { groups[kind].removeLayer(markers[kind][id]); delete markers[kind][id]; }
    });
  }

  // Subscribers (until 5000) in طبقة رسم واحدة (canvas) بدل عنصر لكل subscriber: Map تفتح وتتحرك بلا تقطيع.
  // ألوان Status نفسها, ونافذة Subscriber تُبنى عند opened it only. وضع التحريك يستخدم علامات قابلة للسحب للظاهر منهم only.
  var subCanvas = L.canvas({ padding: 0.3 });
  var SUB_COLOR = { 'is-active': '#16a34a', 'is-expiring': '#f59e0b', 'is-expired': '#dc2626', 'is-new': '#94a3b8' };
  function subStyle(s) {
    var cls = (SUB_STATE[s.state] || SUB_STATE.active)[2];
    return { renderer: subCanvas, radius: s.online ? 7 : 6, weight: s.online ? 3 : 2, color: s.online ? 'rgba(22, 163, 74, .45)' : '#ffffff', opacity: 1, fillColor: SUB_COLOR[cls] || SUB_COLOR['is-active'], fillOpacity: 1 };
  }
  var subDrag = false;      // العلامات الحالية قابلة للسحب (وضع التحريك)

  // البند 58: حالة البرج from MikroTik devices المركّبة owes: كلها Online “is-up”, أحدها Down “is-down”, بلا devices or حالة مجهولة “is-idle”
  function siteState(id) {
    var up = 0, down = 0;
    data.routers.forEach(function (r) { if (r.site_id === id) { if (r.status === 'online') { up++; } else if (r.status === 'offline') { down++; } } });
    return down ? 'is-down' : (up ? 'is-up' : 'is-idle');
  }
  function siteIcon(s) { return SNGeo.icon((cfg.siteTypes[s.type] || {}).icon || 'map-pin', 'mk-site ' + siteState(s.id), 34); }
  function routerIcon(r) { return SNGeo.icon('router', 'mk-router ' + (ROUTER_STATUS[r.status] || ROUTER_STATUS.unknown)[2], 28); }
  function nodeIcon() { return SNGeo.icon('router', 'mk-node', 26); }
  function subIcon(s) { return SNGeo.dot((SUB_STATE[s.state] || SUB_STATE.active)[2] + (s.online ? ' is-online' : '')); }

  function bindDrag(m, type, id) {
    m.on('dragend', function () {
      var p = m.getLatLng();
      SN.api(cfg.positionUrl, { method: 'POST', data: { type: type, id: id, lat: p.lat, lng: p.lng } })
        .then(function () { SN.toast('success', 'Location saved.'); load(); })
        .catch(function () { load(); });
    });
  }

  function render() {
    sync('links', data.links, function (l) {
      return L.polyline([[l.a.lat, l.a.lng], [l.b.lat, l.b.lng]], LINK_STYLE[l.type] || LINK_STYLE.other)
        .bindTooltip(esc((cfg.linkTypes[l.type] || l.type) + (l.capacity ? ' · ' + l.capacity : '') + (l.label ? ' · ' + l.label : '')), { sticky: true, direction: 'top' })
        .bindPopup(linkPopup(l));
    }, function (m, l) {
      m.setLatLngs([[l.a.lat, l.a.lng], [l.b.lat, l.b.lng]]);
      m.setStyle(LINK_STYLE[l.type] || LINK_STYLE.other);
      m.setPopupContent(linkPopup(l));
    });
    var moving = mode === 'move';
    if (moving !== subDrag) {
      // تبديل نوع العلامات: تُبنى from New
      groups.subscribers.clearLayers();
      markers.subscribers = {};
      subDrag = moving;
    }
    var subs = data.subscribers;
    if (moving) {
      var bounds = map.getBounds().pad(0.2);
      subs = subs.filter(function (s) { return bounds.contains([s.lat, s.lng]); }).slice(0, 400);
    }
    sync('subscribers', subs, function (s) {
      var m;
      if (moving) {
        m = L.marker([s.lat, s.lng], { icon: subIcon(s), draggable: true });
        bindDrag(m, 'subscriber', s.id);
      } else {
        m = L.circleMarker([s.lat, s.lng], subStyle(s));
      }
      m._sub = s;
      return m.bindPopup(function (layer) { return subPopup(layer._sub); });
    }, function (m, s) {
      m._sub = s;
      m.setLatLng([s.lat, s.lng]);
      if (moving) { m.setIcon(subIcon(s)); } else { m.setStyle(subStyle(s)); }
    });
    sync('sites', data.sites, function (s) {
      var m = L.marker([s.lat, s.lng], { icon: siteIcon(s), draggable: mode === 'move', zIndexOffset: 200 }).bindPopup(sitePopup(s));
      m.on('click', function () { if (mode === 'link') { pickLinkEnd('site', s.id); } });
      bindDrag(m, 'site', s.id);
      label(m, s.name, 'is-site', 20);
      return m;
    }, function (m, s) { m.setLatLng([s.lat, s.lng]); siteClass(m, s); m.setPopupContent(sitePopup(s)); label(m, s.name, 'is-site', 20); });
    sync('routers', data.routers, function (r) {
      var m = L.marker([r.lat, r.lng], { icon: routerIcon(r), draggable: mode === 'move', zIndexOffset: 400 }).bindPopup(routerPopup(r));
      m.on('click', function () { if (mode === 'link') { pickLinkEnd('router', r.id); } });
      bindDrag(m, 'router', r.id);
      label(m, r.name, 'is-router ' + (ROUTER_STATUS[r.status] || ROUTER_STATUS.unknown)[2], 17);
      return m;
    }, function (m, r) { m.setLatLng([r.lat, r.lng]); m.setIcon(routerIcon(r)); m.setPopupContent(routerPopup(r)); label(m, r.name, 'is-router ' + (ROUTER_STATUS[r.status] || ROUTER_STATUS.unknown)[2], 17); });
    sync('nodes', data.nodes || [], function (n) {
      var m = L.marker([n.lat, n.lng], { icon: nodeIcon(), draggable: mode === 'move', zIndexOffset: 300 }).bindPopup(nodePopup(n));
      m.on('click', function () { if (mode === 'link') { pickLinkEnd('node', n.id); } });
      bindDrag(m, 'node', n.id);
      label(m, n.name, 'is-node', 16);
      return m;
    }, function (m, n) { m.setLatLng([n.lat, n.lng]); m.setPopupContent(nodePopup(n)); label(m, n.name, 'is-node', 16); });

    ['sites', 'routers', 'nodes', 'subscribers', 'links'].forEach(function (k) {
      var el = document.querySelector('[data-count="' + k + '"]');
      if (el) { el.textContent = SN.fmtNum((data[k] || []).length); }
    });
    declutterSoon();
  }

  // ------------------------------------------------------------------------
  // Device and site names on the map: ظاهرة دائماً تحت العلامة, وما يتصادم منها يُخفى كما in Google Maps
  // (MikroTik devices أولاً then Sites), وتظهر عند التكبير or بالمرور on العلامة
  // ------------------------------------------------------------------------
  function label(m, text, cls, dy) {
    var t = m.getTooltip();
    if (t && m._snLabel === text + cls) { return; }
    m._snLabel = text + cls;
    // Refresh Name الظاهر in مكانه (Redo Link Name الدائم كانت تترك القديم in Page)
    if (t) {
      t.options.className = 'mk-label ' + cls;
      var el = t.getElement();
      if (el) {
        Array.prototype.slice.call(el.classList).forEach(function (c) { if (/^is-/.test(c) && c !== 'is-clash') { el.classList.remove(c); } });
        cls.split(/\s+/).forEach(function (c) { if (c) { el.classList.add(c); } });
      }
      m.setTooltipContent(esc(text));
      return;
    }
    m.bindTooltip(esc(text), { permanent: true, direction: 'bottom', offset: [0, dy], className: 'mk-label ' + cls, opacity: 1, interactive: false });
  }

  var labelsOn = true;
  var declutterTimer = null;
  function declutterSoon() {
    clearTimeout(declutterTimer);
    declutterTimer = setTimeout(declutter, 60);
  }
  function declutter() {
    holder.classList.toggle('hide-labels', !labelsOn);
    if (!labelsOn) { return; }
    var box = holder.getBoundingClientRect();
    var taken = Array.prototype.map.call(holder.querySelectorAll('.leaflet-control'), function (c) { return c.getBoundingClientRect(); });
    var overlaps = function (a, b) { return a.left < b.right + 2 && a.right > b.left - 2 && a.top < b.bottom + 2 && a.bottom > b.top - 2; };
    ['routers', 'nodes', 'sites'].forEach(function (kind) {
      if (!map.hasLayer(groups[kind])) { return; }
      Object.keys(markers[kind]).forEach(function (id) {
        var t = markers[kind][id].getTooltip(), el = t && t.getElement();
        if (!el) { return; }
        el.classList.remove('is-clash');
        var r = el.getBoundingClientRect();
        var outside = r.left < box.left || r.right > box.right || r.top < box.top || r.bottom > box.bottom;
        if (outside || taken.some(function (o) { return overlaps(r, o); })) { el.classList.add('is-clash'); return; }
        taken.push(r);
      });
    });
  }
  map.on('zoomend moveend', declutterSoon);
  var labelsBox = document.querySelector('[data-map-labels]');
  if (labelsBox) {
    try { if (localStorage.getItem('sn-map-labels') === '0') { labelsBox.checked = false; } } catch (e) { /* Storage Unavailable */ }
    labelsOn = labelsBox.checked;
    labelsBox.addEventListener('change', function () {
      labelsOn = labelsBox.checked;
      try { localStorage.setItem('sn-map-labels', labelsOn ? '1' : '0'); } catch (e) { /* Storage Unavailable */ }
      declutter();
    });
  }

  function linkPopup(l) {
    var html = '<div class="pop"><div class="pop-title">' + esc(l.a.name) + ' ⟷ ' + esc(l.b.name) + '</div>' +
      '<div class="pop-sub">' + esc(cfg.linkTypes[l.type] || l.type) + (l.capacity ? ' · <span dir="ltr">' + esc(l.capacity) + '</span>' : '') + '</div>' +
      (l.label ? '<div class="pop-sub">' + esc(l.label) + '</div>' : '');
    if (cfg.canManage) {
      html += '<div class="pop-actions"><button type="button" class="btn btn-xs text-danger" data-pop="del-link" data-link="' + esc(String(l.id)) + '">' + SN.icon('trash-2') + 'Delete link</button></div>';
    }
    return html + '</div>';
  }

  // Refresh حالة علامة دون استبدالها (لا تُعاد حركة النبض from أولها and no تُغلق نافذتها)
  function siteClass(m, s) {
    var el = m.getElement && m.getElement(), mk = el && el.querySelector('.mk');
    if (!mk) { m.setIcon(siteIcon(s)); return; }
    var st = siteState(s.id);
    ['is-up', 'is-down', 'is-idle'].forEach(function (c) { mk.classList.toggle(c, c === st); });
  }
  function routerClass(m, r) {
    var el = m.getElement && m.getElement(), mk = el && el.querySelector('.mk');
    var st = (ROUTER_STATUS[r.status] || ROUTER_STATUS.unknown)[2];
    if (!mk) { m.setIcon(routerIcon(r)); return; }
    ['is-online', 'is-offline', 'is-unknown'].forEach(function (c) { mk.classList.toggle(c, c === st); });
  }

  // ------------------------------------------------------------------------
  // البند 59: Dots ضوء تمشي on Links بين الأبراج, وسرعتها حسب Movement الحقيقية on Link
  // (حركة MikroTik devices in الطرف الأقل حركة: ما يعبر Link لا يزيد عنها). عناصر in طبقة خاصة تتحرك بـ transform only
  // بين طرفي Link; تُعاد مواضعها yet التكبير, and no Dots حين لا حركة or مع تقليل Movement
  // ------------------------------------------------------------------------
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var flowPane = map.createPane('flowPane');
  flowPane.style.zIndex = 450;
  flowPane.style.pointerEvents = 'none';
  function siteBps(id) {
    var sum = 0, any = false;
    data.routers.forEach(function (r) { if (r.site_id === id) { any = true; sum += r.bps || 0; } });
    return any ? sum : null;
  }
  function endBps(e) {
    if (e.of === 'router') {
      var r = data.routers.filter(function (x) { return x.id === e.id; })[0];
      return r ? (r.bps || 0) : null;
    }
    return e.of === 'node' ? null : siteBps(e.id);
  }
  function linkBps(l) {
    var a = endBps(l.a), b = endBps(l.b);
    if (a === null) { return b || 0; }
    if (b === null) { return a; }
    return Math.min(a, b);
  }
  function flow() {
    flowPane.innerHTML = '';
    if (reduceMotion || !map.hasLayer(groups.links) || !document.body.animate) { return; }
    data.links.forEach(function (l) {
      var bps = linkBps(l);
      if (!bps) { return; }
      var a = map.latLngToLayerPoint([l.a.lat, l.a.lng]), b = map.latLngToLayerPoint([l.b.lat, l.b.lng]);
      var len = a.distanceTo(b);
      if (len < 24) { return; }
      // Duration: ميجابت More ← أسرع (بين 1.2 and 7 ثوانٍ لكل 300 بكسل تقريباً), وعدد النقاط حسب Length
      var mbps = bps / 1e6, per300 = Math.max(1200, Math.min(7000, 7000 / (1 + Math.log10(1 + mbps))));
      var dur = per300 * Math.max(0.5, len / 300), n = Math.max(2, Math.min(6, Math.round(len / 120)));
      for (var i = 0; i < n; i++) {
        var dot = document.createElement('i');
        dot.className = 'flow-dot is-' + l.type;
        flowPane.appendChild(dot);
        dot.animate([
          { transform: 'translate(' + a.x + 'px,' + a.y + 'px)', opacity: 0 },
          { opacity: 1, offset: 0.12 },
          { opacity: 1, offset: 0.88 },
          { transform: 'translate(' + b.x + 'px,' + b.y + 'px)', opacity: 0 }
        ], { duration: dur, iterations: Infinity, delay: -dur * i / n, easing: 'linear' });
      }
    });
  }
  map.on('zoomstart', function () { flowPane.style.visibility = 'hidden'; });
  map.on('zoomend', function () { flow(); flowPane.style.visibility = ''; });

  function load() {
    return SN.api(cfg.dataUrl, { silent: true }).then(function (d) {
      data = d;
      // أول Open: ضبط حدود Show before الرسم, فتُرسم العلامات once on مستوى التكبير النهائي
      var fit = firstLoad && !cfg.savedView && !/[?&]focus=/.test(window.location.search);
      if (fit) { fitAll(); }
      render();
      flow();
      var un = d.unplaced || {};
      var box = document.querySelector('[data-unplaced]');
      if (box) {
        var parts = [];
        if (un.sites) { parts.push(SN.fmtNum(un.sites) + ' Site'); }
        if (un.routers) { parts.push(SN.fmtNum(un.routers) + ' MikroTik device'); }
        box.hidden = !parts.length;
        box.querySelector('[data-unplaced-text]').textContent = 'Without coordinates: ' + parts.join(' · ');
      }
      if (firstLoad) {
        firstLoad = false;
        if (!fit && !focusTarget() && !cfg.savedView) { fitAll(); }
      }
    }).catch(function () {});
  }

  function reveal(kind, id) {
    var m = markers[kind] && markers[kind][id];
    if (!m) { return false; }
    if (!map.hasLayer(groups[kind])) { map.addLayer(groups[kind]); }
    map.setView(m.getLatLng(), Math.max(map.getZoom(), 17));
    m.openPopup();
    return true;
  }

  /** ?focus=site:5 | router:3 | sub:12 */
  function focusTarget() {
    var f = /[?&]focus=(site|router|node|sub):(\d+)/.exec(window.location.search);
    if (!f) { return false; }
    return reveal({ site: 'sites', router: 'routers', node: 'nodes', sub: 'subscribers' }[f[1]], parseInt(f[2], 10));
  }

  map.on('moveend', function () { if (subDrag) { render(); } });

  var flowKey = '', replaying = false;
  SN.live.on('map', function (list) {
    if (!Array.isArray(list) || !data.routers.length) { return; }
    // أثناء Reboot days: الأبراج تعرض ذلك Time, and Status الحالية تُطبَّق عند الإغلاق
    if (replaying) { list.forEach(function (n) { data.routers.forEach(function (r) { if (r.id === n.id) { r.status = n.status; r.clients = n.clients; r.bps = n.bps; } }); }); return; }
    var byId = {};
    list.forEach(function (r) { byId[r.id] = r; });
    data.routers.forEach(function (r) {
      var n = byId[r.id];
      if (!n) { return; }
      var changed = n.status !== r.status;
      r.status = n.status; r.clients = n.clients; r.bps = n.bps;
      var m = markers.routers[r.id];
      if (m && changed) { routerClass(m, r); label(m, r.name, 'is-router ' + (ROUTER_STATUS[r.status] || ROUTER_STATUS.unknown)[2], 17); }
    });
    data.sites.forEach(function (s) { var m = markers.sites[s.id]; if (m) { siteClass(m, s); } });
    // سرعة النقاط تتغير only حين تتغير Movement on Link ما بوضوح (More from الضعف or Less from النصف)
    var key = data.links.map(function (l) { var v = linkBps(l); return v ? Math.round(Math.log2(v)) : 0; }).join(',');
    if (key !== flowKey) { flowKey = key; flow(); }
  }, { every: 30000 });

  function fitAll() {
    var pts = [];
    data.sites.forEach(function (s) { pts.push([s.lat, s.lng]); });
    data.routers.forEach(function (r) { pts.push([r.lat, r.lng]); });
    (data.nodes || []).forEach(function (n) { pts.push([n.lat, n.lng]); });
    data.subscribers.forEach(function (s) { pts.push([s.lat, s.lng]); });
    if (pts.length > 1) { map.fitBounds(pts, { padding: [40, 40], maxZoom: 16, animate: false }); }
    else if (pts.length === 1) { map.setView(pts[0], 15, { animate: false }); }
  }

  // ------------------------------------------------------------------------
  // Layers والبحث
  // ------------------------------------------------------------------------
  document.querySelectorAll('[data-layer]').forEach(function (cb) {
    var key = 'sn-map-layer-' + cb.getAttribute('data-layer');
    try { if (localStorage.getItem(key) === '0') { cb.checked = false; } } catch (e) { /* Storage Unavailable */ }
    var apply = function () {
      var g = groups[cb.getAttribute('data-layer')];
      if (cb.checked) { map.addLayer(g); } else { map.removeLayer(g); }
      if (cb.getAttribute('data-layer') === 'links') { flow(); }
      try { localStorage.setItem(key, cb.checked ? '1' : '0'); } catch (e) { /* Storage Unavailable */ }
      if (typeof declutterSoon === 'function') { declutterSoon(); }
    };
    cb.addEventListener('change', apply);
    apply();
  });

  var search = document.querySelector('[data-map-search]');
  if (search) {
    search.addEventListener('keydown', function (e) {
      if (e.key !== 'Enter') { return; }
      e.preventDefault();
      var q = search.value.trim().toLowerCase();
      if (!q) { return; }
      var kinds = ['sites', 'routers', 'nodes', 'subscribers'];
      for (var i = 0; i < kinds.length; i++) {
        var list = data[kinds[i]] || [];
        for (var j = 0; j < list.length; j++) {
          if (String(list[j].name).toLowerCase().indexOf(q) !== -1) {
            reveal(kinds[i], list[j].id);
            return;
          }
        }
      }
      SN.toast('info', 'No matching result.');
    });
  }

  // ------------------------------------------------------------------------
  // Administration: Add Site, Links, التحريك
  // ------------------------------------------------------------------------
  function setMode(m) {
    mode = mode === m ? '' : m;
    holder.setAttribute('data-mode', mode);
    document.querySelectorAll('[data-map-act]').forEach(function (b) {
      var on = b.getAttribute('data-map-act') === mode;
      b.classList.toggle('btn-primary', on || (b.getAttribute('data-map-act') === 'add' && mode === ''));
      b.setAttribute('aria-pressed', on ? 'true' : 'false');
    });
    ['sites', 'routers', 'nodes', 'subscribers'].forEach(function (k) {
      Object.keys(markers[k]).forEach(function (id) {
        var mk = markers[k][id];
        if (mk.dragging) { if (mode === 'move') { mk.dragging.enable(); } else { mk.dragging.disable(); } }
      });
    });
    // Subscribers: علامات قابلة للسحب in وضع التحريك only, ورسم سريع in غيره
    if ((mode === 'move') !== subDrag) { render(); }
    if (mode !== 'link') { markLinkFrom(null); }
  }

  /** تمييز الطرف الأول عند رسم Link ({of, id} or null) */
  function endMarker(e) {
    var m = e && markers[KIND_OF[e.of]] && markers[KIND_OF[e.of]][e.id];
    return m && m.getElement ? m.getElement() : null;
  }
  function markLinkFrom(e) {
    var el = endMarker(linkFrom);
    if (el) { el.classList.remove('is-picked'); }
    linkFrom = e;
    el = endMarker(e);
    if (el) { el.classList.add('is-picked'); }
  }

  var siteForm = document.querySelector('[data-site-form]');
  var linkForm = document.querySelector('[data-link-form]');

  function openSite(site, latlng) {
    if (!siteForm) { return; }
    siteForm.reset();
    siteForm.id.value = site ? site.id : '';
    document.querySelector('[data-site-title]').textContent = site ? site.name : 'New site';
    if (site) {
      siteForm.name.value = site.name;
      siteForm.type.value = site.type;
      siteForm.area_id.value = site.area_id || '';
      siteForm.height_m.value = site.height || '';
      siteForm.address.value = site.address || '';
      siteForm.notes.value = site.notes || '';
      siteForm.lat.value = site.lat;
      siteForm.lng.value = site.lng;
    } else if (latlng) {
      siteForm.lat.value = Math.round(latlng.lat * 1e7) / 1e7;
      siteForm.lng.value = Math.round(latlng.lng * 1e7) / 1e7;
    }
    document.querySelector('[data-site-delete]').hidden = !site;
    SN.openModal('site-modal');
  }

  /** قائمة أطراف Link: Sites, MikroTik devices, الراوترات الظاهرة on the map */
  function endOptions() {
    var html = '<option value="">—</option>';
    [['site', 'Sites'], ['router', 'MikroTik devices'], ['node', 'Routers']].forEach(function (g) {
      var list = data[KIND_OF[g[0]]] || [];
      if (!list.length) { return; }
      html += '<optgroup label="' + esc(g[1]) + '">' + list.map(function (x) {
        return '<option value="' + g[0] + ':' + x.id + '">' + esc(x.name) + '</option>';
      }).join('') + '</optgroup>';
    });
    return html;
  }
  function openLink(a, b) {
    if (!linkForm) { return; }
    linkForm.reset();
    var opts = endOptions();
    linkForm.a.innerHTML = opts;
    linkForm.b.innerHTML = opts;
    if (a) { linkForm.a.value = a.of + ':' + a.id; }
    if (b) { linkForm.b.value = b.of + ':' + b.id; }
    SN.openModal('link-modal');
  }

  function pickLinkEnd(of, id) {
    var e = { of: of, id: id };
    if (!linkFrom) {
      markLinkFrom(e);
      map.closePopup();
      return;
    }
    if (linkFrom.of === of && linkFrom.id === id) { return; }
    var a = linkFrom;
    setMode('link');
    map.closePopup();
    openLink(a, e);
  }

  map.on('click', function (e) {
    if (mode === 'add') { setMode('add'); openSite(null, e.latlng); }
    else if (mode === 'router') { setMode('router'); openRouter(null, e.latlng); }
  });

  // ------------------------------------------------------------------------
  // Add device to Map: MikroTik device from the system (مع Edit اسمه), or Router باسمه only
  // ------------------------------------------------------------------------
  var routerForm = document.querySelector('[data-router-form]');
  function routerName(id) {
    var r = (cfg.routers || []).filter(function (x) { return x.id === id; })[0];
    return r ? r.name : '';
  }
  function setKind(k) {
    routerForm.querySelectorAll('[name="kind"]').forEach(function (r) { r.checked = r.value === k; });
    routerForm.querySelectorAll('[data-kind-box]').forEach(function (box) {
      var on = box.getAttribute('data-kind-box') === k;
      box.hidden = !on;
      box.querySelectorAll('input, select').forEach(function (i) { i.disabled = !on; });
    });
    routerForm.querySelectorAll('[data-kind-only]').forEach(function (el) { el.hidden = el.getAttribute('data-kind-only') !== k; });
    var submit = routerForm.querySelector('[data-router-submit]');
    if (submit) { submit.hidden = k === 'mikrotik' && submit.hasAttribute('data-needs-routers'); }
    var del = routerForm.querySelector('[data-node-delete]');
    if (del) { del.hidden = k !== 'node' || !routerForm.node_id.value; }
  }
  function openRouter(id, latlng, node) {
    if (!routerForm) { return; }
    routerForm.reset();
    routerForm.node_id.value = node ? node.id : '';
    routerForm.node_name.value = node ? node.name : '';
    var lat = Math.round(latlng.lat * 1e7) / 1e7, lng = Math.round(latlng.lng * 1e7) / 1e7;
    routerForm.lat.value = lat;
    routerForm.lng.value = lng;
    routerForm.querySelector('[data-router-coords]').textContent = lat.toFixed(6) + ', ' + lng.toFixed(6);
    var editing = !!node || !!id;
    var free = (cfg.routers || []).filter(function (x) { return !x.placed; })[0];
    if (routerForm.id) {
      if (!id && !node) { id = free ? free.id : null; }
      routerForm.id.value = id ? String(id) : '';
      routerForm.name.value = id ? routerName(id) : '';
    }
    var add = routerForm.querySelector('[data-router-new]');
    if (add) { add.href = url('/routers/create') + '?lat=' + lat + '&lng=' + lng; }
    // Edit device or Router Present: بلا اختيار Type. Add New: MikroTik device إن بقي Device ليس on the map, وإلا Router
    routerForm.querySelector('[data-router-kinds]').hidden = editing;
    document.querySelector('[data-router-title]').textContent = node ? node.name : (editing ? routerName(id) : 'Add device');
    setKind(node || (!editing && !free) ? 'node' : 'mikrotik');
    SN.openModal('router-modal');
  }
  if (routerForm) {
    if (routerForm.id) {
      routerForm.id.addEventListener('change', function () { routerForm.name.value = routerName(parseInt(routerForm.id.value, 10)); });
    }
    routerForm.querySelectorAll('[name="kind"]').forEach(function (r) {
      r.addEventListener('change', function () { if (r.checked) { setKind(r.value); } });
    });
    routerForm.addEventListener('submit', function (e) {
      e.preventDefault();
      var kind = (routerForm.querySelector('[name="kind"]:checked') || {}).value;
      if (kind === 'node') {
        var nid = routerForm.node_id.value;
        SN.api(cfg.nodesUrl + (nid ? '/' + nid : ''), { method: 'POST', data: { name: routerForm.node_name.value, lat: routerForm.lat.value, lng: routerForm.lng.value } }).then(function (r) {
          SN.toast('success', r.message);
          SN.closeModal(document.getElementById('router-modal'));
          load().then(function () { reveal('nodes', r.id); });
        });
        return;
      }
      SN.api(cfg.routerUrl, { method: 'POST', form: routerForm }).then(function (r) {
        SN.toast('success', r.message);
        SN.closeModal(document.getElementById('router-modal'));
        (cfg.routers || []).forEach(function (x) { if (x.id === r.id) { x.placed = true; x.name = r.name; } });
        var opt = routerForm.id.querySelector('option[value="' + r.id + '"]');
        if (opt) { opt.textContent = r.name + ' · on the map'; }
        load().then(function () { reveal('routers', r.id); });
      });
    });
    var nodeDel = routerForm.querySelector('[data-node-delete]');
    if (nodeDel) {
      nodeDel.addEventListener('click', function () {
        // Delete فوري مع “Undo” (يعود الراوتر وروابطه)
        SN.api(cfg.nodesUrl + '/' + routerForm.node_id.value + '/delete', { method: 'POST', data: {} }).then(function (r) {
          SN.undoToast(r.message, r.undo, function () { load(); });
          SN.closeModal(document.getElementById('router-modal'));
          load();
        });
      });
    }
  }

  document.addEventListener('click', function (e) {
    var act = e.target.closest('[data-map-act]');
    if (act) {
      var a = act.getAttribute('data-map-act');
      if (a === 'save-view') {
        var c = map.getCenter();
        SN.api(cfg.viewUrl, { method: 'POST', data: { lat: c.lat, lng: c.lng, zoom: map.getZoom() } }).then(function (r) { SN.toast('success', r.message); });
      } else {
        setMode(a);
      }
      return;
    }
    var pop = e.target.closest('[data-pop]');
    if (!pop) { return; }
    var id = parseInt(pop.getAttribute('data-id'), 10);
    var kind = pop.getAttribute('data-pop');
    if (kind === 'edit-site') {
      map.closePopup();
      openSite(data.sites.filter(function (s) { return s.id === id; })[0] || null);
    } else if (kind === 'link-from') {
      if (mode !== 'link') { setMode('link'); }
      markLinkFrom({ of: pop.getAttribute('data-of') || 'site', id: id });
      map.closePopup();
    } else if (kind === 'edit-node') {
      var nn = (data.nodes || []).filter(function (x) { return x.id === id; })[0];
      map.closePopup();
      if (nn) { openRouter(null, L.latLng(nn.lat, nn.lng), nn); }
    } else if (kind === 'edit-router') {
      var rr = data.routers.filter(function (x) { return x.id === id; })[0];
      map.closePopup();
      if (rr) { openRouter(id, L.latLng(rr.lat, rr.lng)); }
    } else if (kind === 'unplace-router') {
      SN.confirm('Remove the device from the map? It stays in the system, and goes back to its tower’s location if it has one.').then(function (ok) {
        if (!ok) { return; }
        SN.api(url('/map/router/' + id + '/remove'), { method: 'POST', data: {} }).then(function (r) {
          SN.toast('success', r.message);
          map.closePopup();
          load();
        });
      });
    } else if (kind === 'del-link') {
      SN.confirm('Delete this link?').then(function (ok) {
        if (!ok) { return; }
        var lk = pop.getAttribute('data-link') || '';
        var path = /^m\d+$/.test(lk) ? '/map/links/' + lk.slice(1) + '/delete' : '/sites/links/' + parseInt(lk, 10) + '/delete';
        SN.api(url(path), { method: 'POST', data: {} }).then(function (r) {
          if (r.undo) { SN.undoToast(r.message, r.undo, function () { load(); }); } else { SN.toast('success', r.message); }
          map.closePopup();
          load();
        });
      });
    }
  });

  if (siteForm) {
    siteForm.addEventListener('submit', function (e) {
      e.preventDefault();
      var id = siteForm.id.value;
      SN.api(id ? cfg.sitesUrl + '/' + id : cfg.sitesUrl, { method: 'POST', form: siteForm }).then(function (r) {
        SN.toast('success', r.message);
        SN.closeModal(document.getElementById('site-modal'));
        load();
      });
    });
    document.querySelector('[data-site-delete]').addEventListener('click', function () {
      var id = siteForm.id.value;
      // Delete فوري مع “Undo” بدل سؤال التأكيد
      SN.api(cfg.sitesUrl + '/' + id + '/delete', { method: 'POST', data: {} }).then(function (r) {
        SN.undoToast(r.message, r.undo, function () { load(); });
        SN.closeModal(document.getElementById('site-modal'));
        load();
      });
    });
  }
  if (linkForm) {
    linkForm.addEventListener('submit', function (e) {
      e.preventDefault();
      SN.api(cfg.mapLinksUrl, { method: 'POST', form: linkForm }).then(function (r) {
        SN.toast('success', r.message);
        SN.closeModal(document.getElementById('link-modal'));
        load();
      });
    });
  }

  // ------------------------------------------------------------------------
  // أدوات تُحمَّل عند الطلب: الطبقة الحرارية and Reboot Today (map-tools.js), and Map ثلاثية الأبعاد (map3d.js)
  // ------------------------------------------------------------------------
  window.SNMap = {
    map: map, cfg: cfg, url: url, markers: markers, label: label,
    data: function () { return data; },
    siteState: siteState,
    replaying: function (on) {
      replaying = !!on;
      if (!replaying) {
        data.sites.forEach(function (s) { var m = markers.sites[s.id]; if (m) { siteClass(m, s); label(m, s.name, 'is-site', 20); } });
      }
    }
  };
  function tool(src, done, fail) {
    var key = 'sn' + src.replace(/\W/g, '');
    if (window[key]) { done(); return; }
    var s = document.createElement('script');
    s.src = src;
    s.onload = function () { window[key] = true; done(); };
    s.onerror = function () { SN.toast('error', 'Could not load.'); if (fail) { fail(); } };
    document.head.appendChild(s);
  }
  var heatBox = document.querySelector('[data-map-heat]');
  if (heatBox) {
    heatBox.addEventListener('change', function () {
      var on = heatBox.checked;
      tool(cfg.toolsSrc, function () { window.SNMapTools.heat(on); });
    });
  }
  var replayBtn = document.querySelector('[data-map-replay]');
  if (replayBtn) {
    replayBtn.addEventListener('click', function () {
      var on = replayBtn.getAttribute('aria-pressed') !== 'true';
      replayBtn.setAttribute('aria-pressed', on ? 'true' : 'false');
      tool(cfg.toolsSrc, function () { window.SNMapTools.replay(on); });
    });
  }

  // البند 92: Map ثلاثية الأبعاد (MapLibre GL المحلي) تُحمَّل عند الضغط only; الزر يظهر حيث يدعم المتصفح WebGL
  var btn3d = document.querySelector('[data-map-3d]');
  if (btn3d && cfg.map3d && ('WebGL2RenderingContext' in window || 'WebGLRenderingContext' in window)) {
    btn3d.hidden = false;
    var set3d = function (on) { btn3d.setAttribute('aria-pressed', on ? 'true' : 'false'); btn3d.classList.toggle('btn-primary', on); };
    btn3d.addEventListener('click', function () {
      if (btn3d.getAttribute('aria-pressed') === 'true') { window.SNMap3D.close(); set3d(false); return; }
      btn3d.classList.add('is-loading');
      var failed = function () { btn3d.classList.remove('is-loading'); };
      // File أنماط المكتبة مع ملفيها بالتوازي, وتُفتح yet وصول الثلاثة
      var waiting = 2, ready = function () {
        if (--waiting) { return; }
        btn3d.classList.remove('is-loading');
        window.SNMap3D.onClose = function () { set3d(false); };
        if (window.SNMap3D.open()) { set3d(true); } else { btn3d.hidden = true; SN.toast('error', 'The 3D map is not supported on this device.'); }
      };
      var css = document.querySelector('link[data-maplibre]');
      if (css) { ready(); } else {
        css = document.createElement('link');
        css.rel = 'stylesheet'; css.href = cfg.map3d.css; css.setAttribute('data-maplibre', '');
        css.onload = ready;
        css.onerror = function () { SN.toast('error', 'Could not load.'); failed(); };
        document.head.appendChild(css);
      }
      tool(cfg.map3d.gl, function () { tool(cfg.map3d.src, ready, failed); }, failed);
    });
  }

  load();
  setInterval(function () { if (!document.hidden && !replaying) { load(); } }, 60000);
  window.addEventListener('resize', function () { map.invalidateSize(); });
})(window, document);
